import {
  ComponentData,
  ComponentMethods,
  ComponentUnique,
  bubbleUpdateWorkTrue,
} from '../types';
import { unregisterMethod, disposeComponent } from '../registry';
import { bumpRenderableVersion, RenderableType } from '../renderable-version';
import {
  isTypeOptedIn,
  getTypeRegistrySet,
  isWithinSubtree,
  sameComponent,
  registerByType,
  registerByName as registerNameEntry,
} from '../component-lookup-registry';
import { NexusT } from './data';

const RENDERABLE_TYPES = new Set<string>([
  'sprite',
  'cell-map',
  'light',
  'vision-source',
]);

export interface NexusMethods extends ComponentMethods {
  addComponent: (
    n: NexusT,
    component: ComponentData,
    registerByName?: boolean,
  ) => void;
  addComponents: (
    n: NexusT,
    components: ComponentData[] | { [index: string]: ComponentData },
  ) => void;
  getComponentById: (
    n: NexusT,
    id: number,
    recursive?: boolean,
  ) => ComponentData | null;
  getComponentByType: (
    n: NexusT,
    type: string,
    recursive?: boolean,
  ) => ComponentData | null;
  getComponentsByType: (
    n: NexusT,
    type: string,
    recursive?: boolean,
  ) => ComponentData[];
  getComponentByName: (
    n: NexusT,
    name: string,
    recursive?: boolean,
  ) => ComponentData | null;
  getComponentsByName: (
    n: NexusT,
    name: string,
    recursive?: boolean,
  ) => ComponentData[];
  getComponentByTypeAndName: (
    n: NexusT,
    type: string,
    name: string,
    recursive?: boolean,
  ) => ComponentData | null;
  getComponentsByTypeAndName: (
    n: NexusT,
    type: string,
    name: string,
    recursive?: boolean,
  ) => ComponentData[];
  dispose: (component: ComponentData) => void;
}

export const Nexus: NexusMethods = {
  type: 'nexus',
  addComponent: (
    n: NexusT,
    component: ComponentData,
    registerByName?: boolean,
  ) => {
    if (component.unique === ComponentUnique.LOCAL) {
      // LOCAL: Dispose existing components of same type in THIS Nexus only
      const existing = n.components.filter((c) => c.type === component.type);
      existing.forEach((c) => disposeComponent(c));
    } else if (component.unique === ComponentUnique.GLOBAL) {
      // GLOBAL: Dispose ALL instances in entire scene hierarchy
      // Find root nexus by traversing up the parent chain
      let root: ComponentData = n;
      while (root.parent && root.parent.type === 'nexus') {
        root = root.parent;
      }

      // Recursively find and dispose all instances of this type in entire scene
      const allInstances = Nexus.getComponentsByType(
        root as NexusT,
        component.type,
        true,
      );
      allInstances.forEach((c) => disposeComponent(c));
    } else if (component.unique === ComponentUnique.NAME) {
      // NAME: Dispose all instances with same type AND same name in entire scene
      let root: ComponentData = n;
      while (root.parent && root.parent.type === 'nexus') {
        root = root.parent;
      }

      const allInstances = Nexus.getComponentsByTypeAndName(
        root as NexusT,
        component.type,
        component.name,
        true,
      );
      allInstances.forEach((c) => disposeComponent(c));
    }

    component.parent = n;
    n.components.push(component);
    // The new component's own `_hasUpdateWork` was already computed at its
    // own construction time (wrapInProxy) -- if it has work, its new
    // ancestors need to reflect that too. If it doesn't, adding it can't
    // change any ancestor's aggregate, so nothing to do.
    if (component._hasUpdateWork) {
      bubbleUpdateWorkTrue(n);
    }
    // See renderable-version.ts -- lets collect-renderables' per-camera cache
    // detect "did a sprite/cell-map/light get added anywhere" cheaply.
    if (RENDERABLE_TYPES.has(component.type)) {
      bumpRenderableVersion(component.type as RenderableType);
    }
    // See component-lookup-registry.ts -- self-checks opt-in internally, so
    // safe to call unconditionally for every add.
    registerByType(component);
    if (registerByName) {
      registerNameEntry(component);
    }
  },
  addComponents: (
    n: NexusT,
    components: ComponentData[] | { [index: string]: ComponentData },
  ) => {
    switch (components.constructor.name) {
      case 'Object':
        for (const key in components) {
          Nexus.addComponent(
            n,
            (components as Record<string, ComponentData>)[key],
          );
        }
        break;
      case 'Array':
        (components as ComponentData[]).forEach((component: ComponentData) =>
          Nexus.addComponent(n, component),
        );
        break;
      default:
        throw new Error(
          `Invalid components type: ${components.constructor.name}`,
        );
    }
  },
  getComponentByType: (n: NexusT, type: string, recursive: boolean = false) => {
    // See component-lookup-registry.ts: for an opted-in type, the registry
    // set is always complete, so it's safe to answer from it alone -- no
    // fallback tree walk needed either way (registry set empty means truly
    // zero instances exist; a match means a real one was found).
    if (isTypeOptedIn(type)) {
      const set = getTypeRegistrySet(type);
      if (recursive) {
        for (const c of set) {
          if (isWithinSubtree(c, n)) return c;
        }
        return null;
      }
      if (set.size < n.components.length) {
        for (const c of set) {
          if (sameComponent(c.parent, n)) return c;
        }
        return null;
      }
      // else: registry isn't smaller here, fall through to the plain scan below
    }

    const match = n.components.find((c) => c.type === type);
    if (match || !recursive) return match ?? null;

    // Recurse into child nexuses only (no intermediate array allocation)
    for (let i = 0; i < n.components.length; i++) {
      const c = n.components[i];
      if (c.type !== 'nexus') continue;
      const childMatch = Nexus.getComponentByType(c as NexusT, type, true);
      if (childMatch) return childMatch;
    }
    return null;
  },
  getComponentsByType: (
    n: NexusT,
    type: string,
    recursive: boolean = false,
  ) => {
    if (isTypeOptedIn(type)) {
      const set = getTypeRegistrySet(type);
      if (recursive) {
        const matches: ComponentData[] = [];
        for (const c of set) {
          if (isWithinSubtree(c, n)) matches.push(c);
        }
        return matches;
      }
      if (set.size < n.components.length) {
        const matches: ComponentData[] = [];
        for (const c of set) {
          if (sameComponent(c.parent, n)) matches.push(c);
        }
        return matches;
      }
      // else: registry isn't smaller here, fall through to the plain scan below
    }

    const matches: ComponentData[] = [];

    // Collect matches in this nexus (no filter allocation)
    for (let i = 0; i < n.components.length; i++) {
      const c = n.components[i];
      if (c.type === type) matches.push(c);
    }

    if (!recursive) return matches;

    // Recurse into child nexuses only (no intermediate array, no spread operator)
    for (let i = 0; i < n.components.length; i++) {
      const c = n.components[i];
      if (c.type !== 'nexus') continue;
      const childMatches = Nexus.getComponentsByType(c as NexusT, type, true);
      for (let j = 0; j < childMatches.length; j++) {
        matches.push(childMatches[j]);
      }
    }
    return matches;
  },
  getComponentByName: (n: NexusT, name: string, recursive: boolean = false) => {
    const match = n.components.find((c) => c.name === name);
    if (match || !recursive) return match ?? null;

    // Recurse into child nexuses only (no intermediate array allocation)
    for (let i = 0; i < n.components.length; i++) {
      const c = n.components[i];
      if (c.type !== 'nexus') continue;
      const childMatch = Nexus.getComponentByName(c as NexusT, name, true);
      if (childMatch) return childMatch;
    }
    return null;
  },
  getComponentsByName: (
    n: NexusT,
    name: string,
    recursive: boolean = false,
  ) => {
    const matches: ComponentData[] = [];

    // Collect matches in this nexus (no filter allocation)
    for (let i = 0; i < n.components.length; i++) {
      const c = n.components[i];
      if (c.name === name) matches.push(c);
    }

    if (!recursive) return matches;

    // Recurse into child nexuses only (no intermediate array, no spread operator)
    for (let i = 0; i < n.components.length; i++) {
      const c = n.components[i];
      if (c.type !== 'nexus') continue;
      const childMatches = Nexus.getComponentsByName(c as NexusT, name, true);
      for (let j = 0; j < childMatches.length; j++) {
        matches.push(childMatches[j]);
      }
    }
    return matches;
  },
  getComponentByTypeAndName: (
    n: NexusT,
    type: string,
    name: string,
    recursive: boolean = false,
  ) => {
    if (isTypeOptedIn(type)) {
      const set = getTypeRegistrySet(type);
      if (recursive) {
        for (const c of set) {
          if (c.name === name && isWithinSubtree(c, n)) return c;
        }
        return null;
      }
      if (set.size < n.components.length) {
        for (const c of set) {
          if (c.name === name && sameComponent(c.parent, n)) return c;
        }
        return null;
      }
      // else: registry isn't smaller here, fall through to the plain scan below
    }

    const match = n.components.find((c) => c.type === type && c.name === name);
    if (match || !recursive) return match ?? null;

    // Recurse into child nexuses only (no intermediate array allocation)
    for (let i = 0; i < n.components.length; i++) {
      const c = n.components[i];
      if (c.type !== 'nexus') continue;
      const childMatch = Nexus.getComponentByTypeAndName(
        c as NexusT,
        type,
        name,
        true,
      );
      if (childMatch) return childMatch;
    }
    return null;
  },
  getComponentsByTypeAndName: (
    n: NexusT,
    type: string,
    name: string,
    recursive: boolean = false,
  ) => {
    if (isTypeOptedIn(type)) {
      const set = getTypeRegistrySet(type);
      if (recursive) {
        const matches: ComponentData[] = [];
        for (const c of set) {
          if (c.name === name && isWithinSubtree(c, n)) matches.push(c);
        }
        return matches;
      }
      if (set.size < n.components.length) {
        const matches: ComponentData[] = [];
        for (const c of set) {
          if (c.name === name && sameComponent(c.parent, n)) matches.push(c);
        }
        return matches;
      }
      // else: registry isn't smaller here, fall through to the plain scan below
    }

    const matches: ComponentData[] = [];

    // Collect matches in this nexus (no filter allocation)
    for (let i = 0; i < n.components.length; i++) {
      const c = n.components[i];
      if (c.type === type && c.name === name) matches.push(c);
    }

    if (!recursive) return matches;

    // Recurse into child nexuses only (no intermediate array, no spread operator)
    for (let i = 0; i < n.components.length; i++) {
      const c = n.components[i];
      if (c.type !== 'nexus') continue;
      const childMatches = Nexus.getComponentsByTypeAndName(
        c as NexusT,
        type,
        name,
        true,
      );
      for (let j = 0; j < childMatches.length; j++) {
        matches.push(childMatches[j]);
      }
    }
    return matches;
  },
  getComponentById: (n: NexusT, id: number, recursive: boolean = false) => {
    if (n.id === id) return n;
    const match = n.components.find((c) => c.id === id);
    if (match || !recursive) return match ?? null;

    // Recurse into child nexuses only (no intermediate array allocation)
    for (let i = 0; i < n.components.length; i++) {
      const c = n.components[i];
      if (c.type !== 'nexus') continue;
      const childMatch = Nexus.getComponentById(c as NexusT, id, true);
      if (childMatch) return childMatch;
    }
    return null;
  },
  dispose: (component: ComponentData) => {
    const n = component as NexusT;
    // Recursively dispose all child components (depth-first). Routed through
    // disposeComponent (not a direct MethodRegistry[c.type].dispose(c) call)
    // so every disposal path -- including this whole-subtree cascade --
    // consistently cleans up the lookup registries (component-lookup-registry.ts)
    // too. disposeComponent's own parent-array removal is redundant here
    // (n.components is wiped wholesale right below regardless), an accepted
    // O(n^2) cost during large-subtree teardown in exchange for one
    // universal disposal choke point instead of a per-type hook.
    n.components.forEach((c) => {
      disposeComponent(c);
    });

    // Unregister script methods if this nexus had a script
    if (n.script) {
      const filename = n.script.split('/').pop() || n.script;
      const baseName = filename
        .replace(/\.omo\.(ts|js)$/, '')
        .replace(/\.(ts|js)$/, '');
      unregisterMethod('nexus', `${baseName}-init`);
      unregisterMethod('nexus', `${baseName}-update`);
    }

    // Clear the components array
    n.components = [];

    // Mark this Nexus as disposed
    n._disposed = true;
  },
};
